from pathlib import Path
import json,re

TARGET="DEV-PRED-A2Z-N1E36-ASSERT-PREBUILD-BINDING-20261007-N1E40"
p=Path.home()/".local/state/prediction-project-executor"/(TARGET+".json")
if not p.is_file():
    raise RuntimeError("FIRST_FAILURE=N1E40_STATE_MISSING")
o=json.loads(p.read_text(encoding="utf-8"))

candidates=[]
def walk(v,path=""):
    if isinstance(v,dict):
        for k,x in v.items():
            np=(path+"."+k) if path else k
            walk(x,np)
    elif isinstance(v,list):
        for i,x in enumerate(v):
            walk(x,f"{path}[{i}]")
    elif isinstance(v,str):
        if any(tok in v for tok in (
            "N1E36_", "ASTRA_", "PREBUILD_", "RuntimeError", "Traceback"
        )):
            candidates.append((path,v))

# Prefer explicit RuntimeError/assertion terminal line.
for path,text in candidates:
    lines=[ln.strip() for ln in text.splitlines() if ln.strip()]
    for ln in reversed(lines):
        if "RuntimeError:" in ln:
            msg=ln.split("RuntimeError:",1)[1].strip()
            raise RuntimeError("FIRST_FAILURE="+msg[:500])

# Fallback to any explicit gate marker.
for path,text in candidates:
    m=re.search(r"(N1E36_[A-Z0-9_:,.'\-]+|ASTRA_[A-Z0-9_:,./'\-]+|PREBUILD_[A-Z0-9_:,./'\-]+)",text)
    if m:
        raise RuntimeError("FIRST_FAILURE="+m.group(1)[:500])

raise RuntimeError("FIRST_FAILURE=UNCLASSIFIED_RECEIPT_SHAPE")
